/* @autogenerated */
package net.civeira.phylax.common.telemetry;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyBoolean;
import static org.mockito.ArgumentMatchers.anyDouble;
import static org.mockito.ArgumentMatchers.anyLong;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.mockStatic;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.util.HashMap;
import java.util.Map;

import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.function.Executable;
import org.mockito.ArgumentCaptor;
import org.mockito.MockedStatic;

import io.opentelemetry.api.common.AttributeKey;
import io.opentelemetry.api.common.Attributes;
import io.opentelemetry.api.trace.Span;
import io.opentelemetry.api.trace.SpanContext;

@DisplayName("Trace guard clauses")
class TraceGuardsUnitTest {

  private static Span validSpan() {
    Span span = mock(Span.class);
    SpanContext ctx = mock(SpanContext.class);
    when(ctx.isValid()).thenReturn(true);
    when(span.getSpanContext()).thenReturn(ctx);
    return span;
  }

  private static void withCurrent(Span span, Executable action) {
    try (MockedStatic<Span> spanStatic = mockStatic(Span.class)) {
      spanStatic.when(Span::current).thenReturn(span);
      assertDoesNotThrow(action);
    }
  }

  @Test
  @DisplayName("Should ignore every call when there is no current span")
  void shouldIgnoreCallsWithoutSpan() {
    // Act / Assert — no call fails when Span.current() returns null
    withCurrent(null, () -> {
      Trace.addEvent("event");
      Trace.addEvent("event", Map.of("k", "v"));
      Trace.setAttribute("key", true);
      Trace.setAttribute("key", 1.0d);
      Trace.setAttribute("key", 1L);
      Trace.setAttribute("key", "value");
    });
  }

  @Test
  @DisplayName("Should not set attributes with null or blank keys")
  void shouldNotSetAttributesWithNullOrBlankKeys() {
    // Arrange — a valid current span
    Span span = validSpan();

    // Act — set attributes using null and blank keys
    withCurrent(span, () -> {
      for (String key : new String[] {null, "  "}) {
        Trace.setAttribute(key, true);
        Trace.setAttribute(key, 1.0d);
        Trace.setAttribute(key, 1L);
        Trace.setAttribute(key, "value");
      }
    });

    // Assert — the span never receives an attribute
    verify(span, never()).setAttribute(anyString(), anyBoolean());
    verify(span, never()).setAttribute(anyString(), anyDouble());
    verify(span, never()).setAttribute(anyString(), anyLong());
    verify(span, never()).setAttribute(anyString(), anyString());
  }

  @Test
  @DisplayName("Should not set a string attribute with a null value")
  void shouldNotSetNullStringAttribute() {
    // Arrange — a valid current span
    Span span = validSpan();

    // Act — set a string attribute with a null value
    withCurrent(span, () -> Trace.setAttribute("key", (String) null));

    // Assert — the span is untouched
    verify(span, never()).setAttribute(anyString(), anyString());
  }

  @Test
  @DisplayName("Should not add events with null or blank names")
  void shouldNotAddEventsWithNullOrBlankNames() {
    // Arrange — a valid current span
    Span span = validSpan();

    // Act — add events with null and blank names
    withCurrent(span, () -> {
      Trace.addEvent(null, Map.of("k", "v"));
      Trace.addEvent("  ", Map.of("k", "v"));
      Trace.addEvent("  ");
    });

    // Assert — no event is recorded
    verify(span, never()).addEvent(anyString());
    verify(span, never()).addEvent(anyString(), any(Attributes.class));
  }

  @Test
  @DisplayName("Should skip attribute entries with null key or value")
  void shouldSkipNullAttributeEntries() {
    // Arrange — a valid span and attributes containing null keys and values
    Span span = validSpan();
    Map<String, String> attributes = new HashMap<>();
    attributes.put(null, "orphan");
    attributes.put("empty", null);
    attributes.put("kept", "yes");

    // Act — add the event with those attributes
    withCurrent(span, () -> Trace.addEvent("event", attributes));

    // Assert — only the complete entry is attached
    ArgumentCaptor<Attributes> captor = ArgumentCaptor.forClass(Attributes.class);
    verify(span).addEvent(eq("event"), captor.capture());
    assertEquals(1, captor.getValue().size());
    assertEquals("yes", captor.getValue().get(AttributeKey.stringKey("kept")));
  }
}
